CREATE TABLE psg_total_rows (
  Id int(11) NOT NULL AUTO_INCREMENT,
  row_id varchar(14) DEFAULT NULL COMMENT ' Уникальный ID строки (14 символов): признак(2)+кодПСГ(4)+0000(4)+кодТерриториального(4)',
  name varchar(100) DEFAULT NULL COMMENT 'Наименование итоговой строки в представлении',
  display_name varchar(100) DEFAULT NULL COMMENT 'Отображаемое наименование (с отступами)',
  psg_id int(11) DEFAULT NULL COMMENT 'ID ПСГ (из таблицы psg или 11 для территориального)',
  category_type varchar(20) DEFAULT NULL COMMENT 'Тип категории: main, gps, fps, other, vpo, chpo, asf',
  category_display varchar(100) DEFAULT NULL,
  total_flag varchar(2) DEFAULT NULL COMMENT 'Признак итога: 01-итог по ПСГ, 02-ГПС, 03-ФПС, 04-другие, 05-ВПО, 06-ЧПО, 07-АСФ',
  norder int(11) DEFAULT NULL COMMENT 'Порядок сортировки (отрицательные числа для группировки)',
  is_active tinyint(1) DEFAULT 1,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (Id),
  INDEX IDX_psg_id (psg_id),
  UNIQUE INDEX IDX_row_id (row_id),
  INDEX IDX_total_flag (total_flag),
  UNIQUE INDEX UK__row_Id (Id),
  UNIQUE INDEX UK_psg_total_rows (psg_id, category_type),
  UNIQUE INDEX UK_psg_total_rows_Id (Id),
  UNIQUE INDEX UK_row_Id (Id)
)
ENGINE = INNODB
AUTO_INCREMENT = 197
AVG_ROW_LENGTH = 141
CHARACTER SET utf8
COLLATE utf8_general_ci
COMMENT = 'Итоговые строки для ПСГ';

